package statuserr

import (
	"errors"
	"fmt"
	"testing"
)

func TestLokiProbe(t *testing.T) {
	lokiProbe("p1", "wrapped status", func() any { buf, code := capture(t); Report(fmt.Errorf("sync failed: %w", Status("disk quota exceeded", 9))); return []any{*code, buf.String()} })
	lokiProbe("p2", "wrapped batch", func() any { buf, code := capture(t); Report(fmt.Errorf("ctx: %w", NewBatch(errors.New("a"), Status("b", 6)))); return []any{*code, buf.String()} })
	lokiProbe("p3", "batch with wrapped status", func() any { _, code := capture(t); Report(NewBatch(errors.New("first"), fmt.Errorf("ctx: %w", Status("late", 11)))); return *code })
}
